alter table public.ils_professional_work_assignment_links add constraint ils_professional_assignment_link_status_chk check (link_status in ('PENDING','APPROVED','ACTIVE','PAUSED','REVOKED','COMPLETED')); create table if not exists public.ils_professional_assignment_lifecycle_audit (id uuid primary key default gen_random_uuid(),assignment_link_id uuid,from_status text,to_status text not null,decision text not null,reason_code text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_lifecycle_audit enable row level security; revoke all on public.ils_professional_assignment_lifecycle_audit from anon,authenticated; create or replace function public.ils_professional_assignment_transition_allowed(p_from text,p_to text) returns boolean language sql immutable as $$ select case when p_from is null and p_to='PENDING' then true when p_from='PENDING' and p_to='APPROVED' then true when p_from='APPROVED' and p_to='ACTIVE' then true when p_from='ACTIVE' and p_to in ('PAUSED','REVOKED','COMPLETED') then true when p_from='PAUSED' and p_to in ('ACTIVE','REVOKED') then true when p_from='REVOKED' and p_to='PENDING' then false when p_from='COMPLETED' and p_to='ACTIVE' then false else false end $$; revoke all on function public.ils_professional_assignment_transition_allowed(text,text) from public,anon,authenticated; grant execute on function public.ils_professional_assignment_transition_allowed(text,text) to authenticated; create index if not exists idx_ils_assignment_lifecycle_audit_link on public.ils_professional_assignment_lifecycle_audit(assignment_link_id,created_at desc);